// src/app/public/list-serve/helpers/list-serve.utils.ts
function censorEmail(email) {
  if (!email)
    return "";
  const [localPart, domain] = email.split("@");
  if (!localPart || !domain)
    return email;
  const len = localPart.length;
  if (len <= 4)
    return localPart.charAt(0) + "***@" + domain;
  if (len <= 7)
    return localPart.slice(0, 2) + "***" + localPart.slice(-2) + "@" + domain;
  return localPart.slice(0, 3) + "***" + localPart.slice(-3) + "@" + domain;
}
function convertListAddressToListId(listAddress) {
  return listAddress ? listAddress.replace("@", ".") : "";
}

