var application_tier_component_default = '<form [formGroup]="appTierForm">\n	<div class="ds-l-row">\n		<div class="ds-l-col--12">\n			<h2 class="ds-u-font-weight--normal ds-u-margin-top--5 ds-u-margin-bottom--0">\n				New Submission\n			</h2>\n		</div>\n	</div>\n	<div class="ds-l-row">\n		<div class="ds-l-col--12">\n			<div *ngIf="isTier1">\n				<app-tier1-submission [tier1SubmissionForm]="appTierForm"></app-tier1-submission>\n			</div>\n			<div *ngIf="!isTier1">\n				<app-tier2-submission [tier2SubmissionForm]="appTierForm"></app-tier2-submission>\n			</div>\n		</div>\n	</div>\n	<ng-container *ngIf="isFilterSelected">\n		<div class="ds-l-row">\n			<div class="ds-l-col--12">\n				<p>\n					<small\n						><em>\n							CMS will utilize the information collected to monitor eligibility with you or your\n							authorized representative(s). In addition, we may perform oversight and quality\n							control activities, combat fraud, and respond to any concerns about the security or\n							confidentiality of the information. You may find additional information regarding this\n							site\u2019s Privacy Policy\n							<a href="https://qualitynet.cms.gov/privacy-policy" target="_blank"\n								>https://qualitynet.cms.gov/privacy-policy</a\n							>\n							<span class="sr-only">opens in new tab</span>.\n						</em></small\n					>\n				</p>\n				<p>\n					<small\n						><em>\n							Section 3087 of the 21st Century Cures Act, signed into law in December 2016, added\n							subsection (f) to section 319 of the Public Health Service Act. This new subsection\n							gives the HHS Secretary the authority to waive Paperwork Reduction Act (PRA) (44 USC\n							3501 et seq.) requirements with respect to voluntary collection of information during\n							a public health emergency (PHE), as declared by the Secretary, or when a disease or\n							disorder is significantly likely to become a public health emergency (SLPHE). Under\n							this new authority, the HHS Secretary may waive PRA requirements for the voluntary\n							collection of information if the Secretary determines that: (1) a PHE exists according\n							to section 319(a) of the PHS Act or determines that a disease or disorder, including a\n							novel and emerging public health threat, is a SLPHE under section 319(f) of the PHS\n							Act; and (2) the PHE/SLPHE, including the specific preparation for and response to it,\n							necessitates a waiver of the PRA requirements. The Office of the Assistant Secretary\n							for Planning and Evaluation (ASPE) has been designated as the office that will\n							coordinate the process for the Secretary to approve or reject each request.\n						</em></small\n					>\n				</p>\n				<p>\n					<small\n						><em>\n							The information collection requirements contained in this information collection\n							request have been submitted and approved under a PRA Waiver granted by the Secretary\n							of Health and Human Services. The waiver can be viewed at\n							<a\n								href="https://aspe.hhs.gov/public-health-emergency-declaration-pra-waivers"\n								target="_blank"\n								>https://aspe.hhs.gov/public-health-emergency-declaration-pra-waivers\n								<span class="sr-only">opens in new tab</span></a\n							>.\n						</em></small\n					>\n				</p>\n			</div>\n		</div>\n		<div class="ng-recaptch">\n			<label for="g-recaptcha-response" class="sr-only">reCAPTCHA verification</label>\n			<re-captcha #recaptcha (resolved)="resolved($event)" name="captcha" theme="light" required></re-captcha>\n		\n		</div>\n		\n\n		<div aria-live="assertive" role="alert">\n			<div class="ds-l-row" *ngIf="showErrorBanner">\n				<div class="ds-l-col--12">\n					<div class="ds-c-alert ds-c-alert--error ds-u-margin-top--5">\n						<div class="ds-c-alert__body">\n							<p class="ds-c-alert__text">\n								There was a problem submitting your submission. Please try again in a few minutes.\n								If the submission still fails, please contact the Service Center for support.\n							</p>\n							<br />\n							<p class="ds-c-alert__text">\n								7:00 AM - 7:00 PM CT<br />\n								Monday - Friday\n							</p>\n							<br />\n							<p class="ds-c-alert__text">\n								E-mail:\n								<a href="mailto:qnetsupport@cms.hhs.gov">qnetsupport&#64;cms.hhs.gov</a><br />\n								Phone: (866) 288-8912<br />\n								TRS: 711<br />\n								Fax: (888) 329-7377\n							</p>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n		<div aria-live="assertive" role="alert">\n			<div class="ds-l-row" *ngIf="showFileInvalid">\n				<div class="ds-l-col--12">\n					<div class="ds-c-alert ds-c-alert--error ds-u-margin-top--5">\n						<div class="ds-c-alert__body" *ngFor="let message of fileInvalidMessages">\n							<p class="ds-c-alert__text">\n								{{ message }}\n							</p>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n\n		<button\n			[disabled]="appTierForm.invalid || !isCaptchaValid"\n			class="ds-c-button ds-c-button--primary ds-c-button--big ds-u-margin-top--5"\n			type="submit"\n			(click)="submitHospitalMeasures()"\n		>\n			Submit\n		</button>\n	</ng-container>\n</form>\n';

