var events_calendar_component_default = `<app-public-header></app-public-header>
<main>
	<section class="page-header">
		<div class="ds-l-container">
			<div class="ds-l-row">
				<div class="ds-l-md-col--8">
					<div class="breadcrumbs">
						<p>
							<a href="../" data-mce-href="../">Home</a> /
							<a href="../qioprogram" data-mce-href="../">QIO Program</a> /
						</p>
					</div>
					<h1 class="page-title page-focus">Events Calendar</h1>
				</div>
				<div class="ds-l-md-col--4"></div>
			</div>
		</div>
	</section>

	<section class="page-section">
		<div class="ds-l-container">
			<div class="ds-l-row">
				<div class="ds-l-lg-col--12">
					<qnp-formly-form
						[form]="eventsCalendarForm"
						[formFields]="eventsCalendarInfoFormFields"
						[isHorizontalForm]="true"
						[isAdvancedSearchExactMatchRequired]="false"
						[fullWidth]="false"
						role="application"
					></qnp-formly-form>
					<button
						type="button"
						id="resetButton"
						class="btn btn-link"
						(click)="resetForm()"
						[disabled]="isResetDisabled"
					>
						Reset
					</button>
					<button type="button" id="publishButton" class="btn btn-primary" (click)="getResults()">
						Apply
					</button>
				</div>
			</div>
			<ng-container *ngIf="totalItems === 0">
				<p>No search results found for the selected criteria. Please try again.</p>
			</ng-container>
			<div class="row" *ngIf="totalItems > 0">
				<div class="col-lg-12">
					<h1>Search Results ({{ totalItems || 0 }})</h1>
				</div>
			</div>
			<div class="row" *ngIf="!isLoading && events.length !== 0">
				<div class="col-12">
					<table class="table table-responsive-sm table-striped">
						<thead>
							<tr>
								<th>Title</th>
								<th
									(click)="changeSort()"
									(keydown.enter)="changeSort()"
									(keydown.space)="changeSort()"
									tabindex="0"
									role="button"
								>
									Date
									<span
										class="sort-icon"
										[ngClass]="{
											'ion-ios-arrow-up': sortOrder === 'asc',
											'ion-ios-arrow-down': sortOrder === 'desc'
										}"
									></span>
								</th>
								<th>Link</th>
							</tr>
						</thead>
						<tbody>
							<tr *ngFor="let event of events">
								<td>{{ event.articleTitle }}</td>
								<td>{{ event.articleDate }}</td>
								<td><a [href]="baseUrl + event.permalink" target="_blank">View Event</a></td>
							</tr>
						</tbody>
					</table>
				</div>
			</div>
			<div class="row mt-3" *ngIf="totalItems > 10">
				<div class="col-md-8">Displaying {{ getCurrentDisplayRange() }} of {{ totalItems }}</div>
				<div class="col-md-4 d-flex justify-content-end">
					<ngb-pagination
						[collectionSize]="totalItems"
						[(page)]="currentPage"
						[pageSize]="pageSize"
						[maxSize]="10"
						[boundaryLinks]="true"
						(pageChange)="setPage($event)"
						aria-label="Pagination"
						appFocusOnPageChange
					></ngb-pagination>
				</div>
			</div>
		</div>
	</section>
</main>

<div class="hcms-loader" [ngClass]="{ loading: isLoading }">
	<ess-loader></ess-loader>
</div>

<app-public-footer></app-public-footer>
`;

